Lemma cl_digits : forall (k j : nat) (Q : machine_state -> Prop) rax spx gp tp t0 t1 t2 s0 s1 (a2 : word) a4 a5 a6 a7 s2 s4 s5 s8 s9 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m1 : mem) (vp vq vl : Z) (vbs : list byte) (P0 P3 N1 : Z),
  (Z.to_nat vl - j = k)%nat -> (j < Z.to_nat vl)%nat ->
  bytes_at asegs m1 vp vbs -> accessible m1 vp (Z.of_nat (length vbs)) -> mem_inv asegs m1 ->
